/* a staircase through values v[0..n-1], each held for one sample of width dx from x0; level 0 at yc, k px per volt; starts at s0 */
const CM_stair=(v,s0,x0,dx,yc,k,col,w=4,ex='')=>{let p=[`${x0},${(yc-k*s0).toFixed(1)}`];v.forEach((q,i)=>{const x=x0+i*dx;p.push(`${x},${(yc-k*(i?v[i-1]:s0)).toFixed(1)}`,`${x},${(yc-k*q).toFixed(1)}`,`${x+dx},${(yc-k*q).toFixed(1)}`)});return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" ${ex}/>`};
/* delta modulation of samples xs with step d from staircase value s0: bits b and staircase st (the book's rule b = 1 if x[n] >= x~[n-1]) */
const CM_dm=(xs,d,s0=0)=>{let s=s0,b=[],st=[];xs.forEach(x=>{const bit=x>=s-1e-9?1:0;s=+(s+(bit?d:-d)).toFixed(6);b.push(bit);st.push(s)});return {b,st}};
