const CM_open=(()=>{let r=0,p=0,o=[];CM_ramp.forEach(x=>{r+=CM_qz(x-p);p=x;o.push(r)});return o})();   /* predicts from the true x */
const CM_closed=(()=>{let r=0,o=[];CM_ramp.forEach(x=>{r+=CM_qz(x-r);o.push(r)});return o})();        /* predicts from x~ */
